/**
 * The Open Badges 3.0 JSON Schemas, vendored from the specification.
 *
 * One module per schema, generated by `scripts/refresh-ob-schemas.mjs` from
 * the schemas embedded in the OB 3.0 spec appendix: the VC 1.1-only `…v1p1`
 * schemas are published nowhere else. Their `$id`s do not resolve; nothing
 * here is ever fetched.
 *
 * Internal: not exported from any public entry point.
 */

import { achievementCredential } from './achievement-credential.js';
import { achievementCredentialV1p1 } from './achievement-credential-v1p1.js';
import { endorsementCredential } from './endorsement-credential.js';
import { endorsementCredentialV1p1 } from './endorsement-credential-v1p1.js';

/** One vendored schema, with what it applies to and its provenance. */
export interface VendoredObSchema {
  /** The schema's `$id` as embedded in the spec. It does not resolve. */
  id: string;
  /** Spec appendix section and class, e.g. `E.2.1.2 AchievementCredential`. */
  specSection: string;
  /** The Open Badges credential type the schema validates. */
  obType: 'OpenBadgeCredential' | 'EndorsementCredential';
  /** The VC data model version the schema accepts, and only that one. */
  vcVersion: 'v1' | 'v2';
  /** SHA-256 (hex) of `JSON.stringify(schema)`, recorded at generation. */
  sha256: string;
  /**
   * The JSON Schema (draft 2020-12). Typed loosely on purpose: a literal type
   * would put the whole schema into the emitted declarations.
   */
  schema: Record<string, unknown>;
}

/** The four vendored schemas: one per OB credential type and VC version. */
export const VENDORED_OB_SCHEMAS: readonly VendoredObSchema[] = [
  achievementCredential,
  achievementCredentialV1p1,
  endorsementCredential,
  endorsementCredentialV1p1
];
